const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.connect}</svg>`;
const services=[['mobile','Mobile recharge','Local mobile top-ups and bill payments.'],['globe','International top-up','Recharge mobile numbers abroad.'],['utility','Utility bills','Explore available utility payment services.'],['transport','Transport & fines','Transport-related services and fine payments.'],['shopping','Shopping & entertainment','Online purchases, gaming and digital services.'],['heart','Charitable giving','Explore available charity payment options.']];
const servicesCatalog=[["mobile","Mobile & internet","Mobile and internet payments.",["Etisalat prepaid and postpaid","Etisalat eLife","du prepaid bundles"]],["utility","Utilities & municipality","Essential regional payments.",["FEWA (as listed)","Ajman Sewerage"]],["transport","Transport & government","Moving around town.",["Salik","Ajman Transport","Dubai Police","Masaar Card"]],["shopping","Digital & entertainment","Digital goods and services.",["iTunes Store UAE","Xbox Live","PlayStation Store","Office 365"]],["heart","Charitable giving","Supporting the community.",["Zakat Fund","Dubai Charity Association"]],["globe","International top-ups","Selected destinations from the international directory.",["Saudi Arabia","Oman","India","Pakistan","Philippines","France"]]];
const servicesPage=()=>`<div class="host-hero"><section class="wrap hero"><div><div class="breadcrumb"><a href="/">Home</a> / Payment services</div><p class="eyebrow">Payment services</p><h1>All your everyday payments.<br><em>One helpful place.</em></h1><p class="intro">Explore phone top-ups, utility bills, transport, digital purchases and more with NT.Payments self-service kiosks.</p><div class="actions"><a class="btn" href="/find-a-kiosk/">Find a kiosk <span>→</span></a><a class="text-link" href="/support/">Customer support →</a></div><p class="micro">Independent redesign concept. Check service and kiosk availability before payment.</p></div><div class="directory-hero-art"><p class="eyebrow">Made for everyday needs</p><div class="directory-hero-tiles">${servicesCatalog.slice(0,4).map(g=>`<div class="directory-hero-tile"><span class="icon">${icon(g[0])}</span><strong>${g[1]}</strong></div>`).join('')}</div></div></section></div><section class="wrap"><div class="sectionhead"><div><p class="eyebrow">Explore payment categories</p><h2>What would you<br>like to pay?</h2></div><p>Representative examples based on NT.Payments’ published service directory. Availability varies by provider and kiosk.</p></div><div class="directory-grid">${servicesCatalog.map((g,i)=>`<article class="directory-card"><div class="directory-iconline"><span class="icon">${icon(g[0])}</span><span class="micro">0${i+1}</span></div><h3>${g[1]}</h3><p>${g[2]}</p><ul>${g[3].map(item=>`<li>${item}</li>`).join('')}</ul></article>`).join('')}</div><div class="directory-note"><div><strong>Looking for a specific service?</strong><p>This independent design is not a live inventory. Confirm current services, fees and conditions with NT.Payments before paying.</p></div><a class="text-link" href="https://ntpayments.com/en/payments/list-of-services/" target="_blank" rel="noopener noreferrer">Official directory ↗</a></div></section><section class="soft"><div class="wrap directory-bottom"><div><p class="eyebrow">Your next step</p><h2>Find a place<br>to make a payment.</h2><p>Check the available services and follow the instructions at the payment kiosk.</p></div><div class="actions"><a class="btn" href="/find-a-kiosk/">Find a kiosk <span>→</span></a><a class="text-link" href="/support/">Get support →</a></div></div></section>`;

function walletPhone(){return `<div class="wallet-visual"><div class="phone liquid-phone" aria-label="NT.Wallet design concept with sample balance"><div class="phone-status"><span>9:41</span><span>● ▰</span></div><div class="app-heading"><b><span>NT.</span>Wallet</b><span class="avatar">JD</span></div><p class="app-greeting">Hello, Jamie</p><div class="balance"><span><i></i> Available balance</span><strong><small>AED</small> 250.00</strong><div class="balance-bottom"><span>Demo balance</span><span>＋ Top up</span></div></div><div class="app-label">Quick payments <span>View all</span></div><div class="app-services"><div><span class="app-brand du"><img src="/assets/du-logo.svg" alt="du" width="34" height="28"></span><small>du</small></div><div><span class="app-brand etisalat">e&amp;</span><small>Etisalat</small></div><div><span class="app-brand government">${icon('utility')}</span><small>Dubai services</small></div></div><div class="app-label">Your everyday essentials</div><div class="app-row">${icon('mobile')}<span>Mobile recharge<small>Keep your connections going</small></span><span>›</span></div><div class="app-row">${icon('transport')}<span>Transport &amp; fines<small>Payments for your next journey</small></span><span>›</span></div><div class="app-tabs"><span>⌂ Home</span><span>⇄ Activity</span><span>◯ Profile</span></div><p class="app-disclaimer">Interface concept · Sample balance and service tiles</p></div></div>`}
const home=()=>`<section class="wrap hero"><div><p class="eyebrow">Everyday payments, across the UAE</p><h1>Everyday payments.<br><em>Closer to you.</em></h1><p class="intro">Pay bills and recharge mobile numbers at NT.Payments self-service kiosks across the UAE. Find your service, then find a kiosk.</p><div class="actions"><a class="btn kiosk-cta" href="#find">${icon("pin")}<span>Find a kiosk</span></a><a class="text-link" href="/payments/list-of-services/">Explore services</a></div><p class="micro">Choose a service. Check the details. Make your payment.</p></div><div class="home-product-photo"><img src="/assets/kiosk-hero-enhanced.png" alt="Close-up of an NT.Payments self-service kiosk touchscreen"><div class="photo-editorial"><span class="photo-kicker">NT.PAYMENTS</span><strong>Everyday services.<br>At your fingertips.</strong><span class="photo-accent" aria-hidden="true"></span></div></div></section><div class="routebar" aria-label="Choose your path">${[['pay','I want to pay','Explore payment services','/payments/list-of-services/'],['store','I own a location','Host a payment kiosk','#host'],['connect','I provide a service','Connect with the network','#providers'],['screen','I want to advertise','Explore screen advertising','#home/advertisers']].map(([i,t,d,h])=>`<a href="${h}"><span class="route-icon">${icon(i)}</span><span class="route-copy"><strong>${t}</strong><small>${d}</small></span></a>`).join('')}</div><section class="wrap" id="services"><div class="sectionhead"><div><p class="eyebrow">Payments for everyday life</p><h2>Your everyday services.<br>One place to start.</h2></div><p>Start with your everyday needs.<br>Available providers and payment options vary by service; check before paying.</p></div><div class="grid">${services.map(([glyph,title,desc])=>`<a class="service" href="/payments/list-of-services/"><span class="icon" aria-hidden="true">${icon(glyph)}</span><div class="service-title"><h3>${title}</h3><span class="service-arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M6 18 18 6M6 6h12v12"/></svg></span></div><p>${desc}</p></a>`).join('')}</div><p class="micro" style="margin-top:20px">Explore the service directory for available providers and payment options.</p></section><section class="soft"><div class="wrap"><p class="eyebrow">From here to paid</p><h2>A few clear steps.<br>Then back to your day.</h2><div class="steps"><div><div class="step-num">01 / FIND</div><h3>Find a kiosk near you</h3><p>Use the official kiosk map to look for a convenient location.</p></div><div><div class="step-num">02 / CHECK</div><h3>Choose your service</h3><p>Follow the on-screen instructions. Review your account details, amount and any fees before confirming.</p></div><div><div class="step-num">03 / KEEP</div><h3>Keep your confirmation</h3><p>Keep the receipt or transaction reference so support can help if you need it.</p></div></div></div></section><section class="wrap find" id="find"><div class="location-art" aria-label="Decorative location illustration"><span class="location-pill"><b aria-hidden="true">⌖</b> Your next stop: a nearby kiosk.</span><span class="art-label">Illustration only · no kiosk locations shown</span></div><div><p class="eyebrow">Closer to your everyday</p><h2>Find your next<br>payment stop.</h2><p class="intro">Look for NT.Payments kiosks using the official location map.</p><a class="btn" href="#find">Explore the kiosk finder <span>→</span></a><p class="micro" style="margin-top:16px">Opens the official website. If the map is unavailable, contact customer support for help finding a kiosk.</p><a class="text-link" href="#support">Get location help →</a></div></section><section class="wrap" style="padding-top:0"><div class="wallet"><div><p class="eyebrow">Meet NT.Wallet</p><h2>At the kiosk.<br>On your phone.</h2><p>Top up NT.Wallet with cash at a kiosk, then pay for everyday services from your phone.</p><a class="btn" href="#wallet">Explore NT.Wallet <span>→</span></a><p class="micro" style="color:#d5e0d8;margin-top:15px">Check the official app information for current services and recharge instructions.</p></div>${walletPhone()}</div></section><section class="soft business" id="business"><div class="wrap"><div class="sectionhead"><div><p class="eyebrow">Build connections with us</p><h2>Let’s connect<br>your business.</h2></div></div><div class="grid"><article class="service"><span class="icon">${icon("store")}</span><h3>Your space. A new service.</h3><p>Explore hosting a payment kiosk at your shop, supermarket, hotel or other business location.</p><div class="actions"><a class="text-link" href="#host">Host a kiosk →</a></div></article><article class="service" id="providers"><span class="icon">${icon("connect")}</span><h3>Bring your service closer.</h3><p>Discuss adding a self-service payment channel for your customers through NT.Payments.</p><div class="actions"><a class="text-link" href="#providers">Explore provider opportunities →</a></div><a class="text-link" href="#contacts">Contact our team →</a></article><article class="service" id="advertisers"><span class="icon">${icon("screen")}</span><h3>Put your brand on screen.</h3><p>Explore advertising on payment kiosk displays and NT.Media promotional screens.</p><div class="actions">${ext(official+'cooperation/advertisers/','Advertising opportunities')}</div><a class="text-link" href="#contacts">Contact our team →</a></article></div></div></section>${support()}`;
function support(){return `<section class="wrap support" id="support"><div><p class="eyebrow">Here when you need us</p><h2>Need help with a payment?</h2><p>Keep your transaction reference handy.<br>UAE customer care: 600 542 521.</p></div><div class="support-contact"><div class="support-buttons"><a class="btn" href="#support">Get customer support <span>→</span></a><a class="support-call" href="tel:600542521">Call 600 542 521</a></div><p class="micro" style="margin-top:15px">Payment questions? Find the right way to reach our team.</p></div></section>`}
const host=()=>`<div class="host-hero"><section class="wrap hero"><div><div class="breadcrumb"><a href="#home">Home</a> / Host a kiosk</div><p class="eyebrow">For location owners</p><h1>Your location.<br><em>Everyday convenience.</em></h1><p class="intro">Bring everyday payment services into your business with an NT.Payments self-service kiosk.</p><div class="actions"><a class="btn" href="#host/apply">Explore hosting <span>↓</span></a></div><p class="micro">Shops · Supermarkets · Hotels · Pharmacies<br>Other location types subject to assessment.</p></div>${product()}</section></div><section class="wrap"><p class="eyebrow">Make your location more useful</p><h2>Everyday convenience.<br>Right inside your business.</h2><div class="facts"><div class="fact"><strong>Do you have 1 free square metre?</strong><p>One square metre of space. Final layout needs assessment.</p></div><div class="fact"><strong>A power connection</strong><p>A power socket to get connected. We’ll review technical and connectivity needs with you.</p></div><div class="fact"><strong>Shared commission</strong><p>Share commission fees for accepted payments. Commercial terms are agreed with you.</p></div></div><div class="commission"><div><p class="eyebrow">How the model works</p><h2 style="font-size:32px">Payments at your location.<br>A share of commission.</h2></div><div><p>Earn a share of commission on accepted payments at your location. Income depends on payment activity and your agreed commercial terms.</p><p>Let’s discuss eligible transactions, commission rates, settlement timing, costs and responsibilities for your location.</p>${ext(official+'cooperation/landlords/','More about hosting')}</div></div></section><section class="soft"><div class="wrap"><p class="eyebrow">A clear next step</p><h2>From an available space<br>to a hosting conversation.</h2><p class="note">Assessment, installation details and timelines are agreed individually.</p><div class="steps"><div><div class="step-num">01 / INTRODUCE</div><h3>Tell us about your location</h3><p>Share the business type, country, location and a way to contact you.</p></div><div><div class="step-num">02 / ASSESS</div><h3>Review the fit together</h3><p>Discuss space, access, technical needs and commercial terms with the team.</p></div><div><div class="step-num">03 / AGREE</div><h3>Plan the next steps</h3><p>If the location is accepted, agree responsibilities and a possible installation plan.</p></div></div></div></section><section class="wrap faq-form"><div class="faq"><p class="eyebrow">Before you get started</p><h2>Good questions.<br>Clear expectations.</h2>${[['Is my business suitable?','Supermarkets, shops, hotels and pharmacies can offer customers a convenient payment stop. Contact us to assess your location and confirm eligibility.'],['How much space do I need?','Plan for one square metre of space. We’ll confirm dimensions, accessibility and clearance requirements for your location.'],['How much will I earn?','You receive a share of commission for accepted payments. Your rate, settlement schedule and any costs are agreed in writing. Income varies with payment activity.'],['Who installs and maintains the kiosk?','We’ll discuss installation, servicing, connectivity, cash handling and maintenance responsibilities before you commit.'],['Can I submit a real enquiry here?','This is an interview prototype. The form saves example leads in this browser’s demo admin; nothing is sent to NT.Payments. Use the official contact page for a real enquiry.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="formbox" id="apply"><p class="eyebrow">Start a conversation</p><h2 style="font-size:32px">Could your location<br>be the next stop?</h2><p style="font-size:14px;color:#616a69">Demo only. Use fictional details. Examples are saved in this browser’s demo admin; nothing is sent to NT.Payments; all fields are required.</p><form id="host-form" novalidate autocomplete="off"><label>Full name<input name="name" required maxlength="80" aria-describedby="name-error"><span class="error" id="name-error"></span></label><label>Company<input name="company" required maxlength="100" aria-describedby="company-error"><span class="error" id="company-error"></span></label><label>Location type<select name="venue" required aria-describedby="venue-error"><option value="">Select type</option>${['Shop','Supermarket','Hotel','Pharmacy','Other commercial location'].map(x=>`<option>${x}</option>`).join('')}</select><span class="error" id="venue-error"></span></label><label>Country<select name="country" required aria-describedby="country-error"><option value="UAE">United Arab Emirates (UAE)</option><option value="KSA">Saudi Arabia (KSA)</option><option value="Qatar">Qatar</option></select><span class="error" id="country-error"></span></label><label id="region-field">Emirate<select name="emirate" required aria-describedby="emirate-error"><option value="">Select emirate</option>${['Abu Dhabi','Dubai','Sharjah','Ajman','Umm Al Quwain','Ras Al Khaimah','Fujairah'].map(x=>`<option>${x}</option>`).join('')}</select><span class="error" id="emirate-error"></span></label><label class="full">Email or phone<input name="contact" required maxlength="120" placeholder="name@example.com or +971…" aria-describedby="contact-error"><span class="error" id="contact-error"></span></label><p class="micro full" id="form-note">This button validates and saves an example lead in this browser’s demo admin. It does not contact NT.Payments.</p><button class="btn full" type="submit" aria-describedby="form-note">Check demo enquiry <span>→</span></button></form><div id="success" class="success hidden" role="status" tabindex="-1"><h3>Demo complete. Nothing was sent.</h3><p>Your example passed validation. This was not an application to NT.Payments. The entered values have been cleared and have not been saved.</p><button class="btn" id="again">Try again ↺</button></div><p class="micro" style="margin-top:20px">Ready for a real conversation? <a class="text-link" href="#contacts">Contact us →</a></p></div></section>${support()}`;
const providers=()=>`<div class="host-hero"><section class="wrap hero"><div><div class="breadcrumb"><a href="#home">Home</a> / Providers</div><p class="eyebrow">For service providers</p><h1>Your service.<br><em>Within easy reach.</em></h1><p class="intro">Give customers another way to pay. Connect your services to the NT.Payments self-service kiosk network across the UAE.</p><div class="actions"><a class="btn" href="#providers/apply">Let’s discuss integration <span>→</span></a></div><p class="micro">An additional payment channel for your customers.</p></div><div class="provider-art"><div class="network-core">${icon('connect')}<strong>NT.Payments</strong><span>Self-service payment network</span></div><div class="network-node node-one">${icon('mobile')}<span>Mobile services</span></div><div class="network-node node-two">${icon('utility')}<span>Everyday bills</span></div><div class="network-node node-three">${icon('shopping')}<span>Digital services</span></div><span class="art-label">Illustrative service network</span></div></section></div><section class="wrap"><p class="eyebrow">A new route to your customers</p><h2>More ways to pay.<br>One connected experience.</h2><div class="grid"><article class="service"><span class="icon">${icon('globe')}</span><h3>Extend your reach</h3><p>Bring your service into the places people visit through an established kiosk network.</p></article><article class="service"><span class="icon">${icon('pay')}</span><h3>Add a payment channel</h3><p>Let customers make payments through a self-service experience alongside your existing channels.</p></article><article class="service"><span class="icon">${icon('connect')}</span><h3>Explore the right fit</h3><p>Discuss how kiosk payments can support your service and customer journey.</p></article></div></section><section class="soft"><div class="wrap"><p class="eyebrow">Let’s build the connection</p><h2>From your service<br>to a payment journey.</h2><div class="steps"><div><div class="step-num">01 / DISCUSS</div><h3>Tell us what you offer</h3><p>Introduce your service, customers and payment needs.</p></div><div><div class="step-num">02 / REVIEW</div><h3>Explore the integration</h3><p>Review service availability, technical requirements and commercial terms together.</p></div><div><div class="step-num">03 / PLAN</div><h3>Agree the next steps</h3><p>Define the customer experience and an implementation plan that fits your service.</p></div></div><p class="micro">Requirements, responsibilities and timelines are agreed for each integration.</p></div></section><section class="wrap faq-form"><div class="faq"><p class="eyebrow">Before we connect</p><h2>A conversation<br>worth starting.</h2><details><summary>What services can be connected?</summary><p>Tell us about your service and where your customers need to pay. Availability and eligibility are assessed individually.</p></details><details><summary>What does integration involve?</summary><p>Technical requirements, transaction handling, reconciliation, support and commercial terms need to be reviewed together.</p></details><details><summary>How much does it cost?</summary><p>Contact the team to discuss the commercial model for your service. No standard fee or implementation timeline is quoted here.</p></details></div><div class="formbox" id="apply"><p class="eyebrow">Connect your service</p><h2>Let’s explore<br>the opportunity.</h2><p class="micro">Demo only. Use example details. Examples are saved in this browser’s demo admin; nothing is sent to NT.Payments.</p><form id="provider-form" novalidate autocomplete="off"><label>Full name *<input name="name" required maxlength="80" aria-describedby="provider-name-error"><span class="error" id="provider-name-error"></span></label><label>Company *<input name="company" required maxlength="100" aria-describedby="provider-company-error"><span class="error" id="provider-company-error"></span></label><label>Work email *<input name="email" type="email" required maxlength="120" aria-describedby="provider-email-error"><span class="error" id="provider-email-error"></span></label><label>Phone number<input name="phone" type="tel" maxlength="30" aria-describedby="provider-phone-error"><span class="error" id="provider-phone-error"></span></label><label>Country *<select name="country" required aria-describedby="provider-country-error"><option value="">Select country</option><option>UAE</option><option>KSA</option><option>Qatar</option><option>Other</option></select><span class="error" id="provider-country-error"></span></label><label>Service category *<select name="category" required aria-describedby="provider-category-error"><option value="">Select category</option>${['Telecom & mobile','Utilities','Transport','Digital & entertainment','Retail & e-commerce','Other'].map(x=>`<option>${x}</option>`).join('')}</select><span class="error" id="provider-category-error"></span></label><label class="full">Tell us about your service *<textarea name="question" required rows="4" maxlength="2000" aria-describedby="provider-question-error"></textarea><span class="error" id="provider-question-error"></span></label><button class="btn full" type="submit">Explore integration <span>→</span></button><p class="micro full">* Required fields. This demo saves a browser-local lead; it does not submit an integration request.</p></form><div id="provider-success" class="success hidden" role="status" tabindex="-1"><h3>Demo complete. Nothing was sent.</h3><p>Your example enquiry passed validation. All fields have been cleared; no data was sent or saved.</p><button class="btn" id="provider-again">Try again ↺</button></div></div></section>`;
