const contacts=()=>`<section class="wrap contact-intro"><div class="breadcrumb"><a href="#home">Home</a> / Contact us</div><p class="eyebrow">Let’s talk</p><h1>A question.<br><em>A new connection.</em></h1><p class="intro">From payment support to business partnerships, find the right way to reach NT.Payments.</p></section><section class="wrap contact-layout" style="padding-top:0"><div><div class="contact-help"><span class="icon">${icon('mobile')}</span><h2>Payment support</h2><p>Have a transaction question? Keep your receipt or payment reference handy.</p><a class="contact-number" href="tel:600542521">600 542 521</a><div class="actions"><a class="text-link" href="https://wa.me/971501956593" target="_blank" rel="noopener">WhatsApp ↗</a><a class="text-link" href="mailto:support@ntpayments.com">Email support ↗</a></div></div><div class="contact-business"><p class="eyebrow">For business</p><h3>A location, a service or a campaign?</h3><p>Tell us what you have in mind and start a conversation with the team.</p><a class="text-link" href="mailto:info@ntpayments.com">info@ntpayments.com ↗</a></div></div><div class="formbox"><p class="eyebrow">Get in touch</p><h2>How can we help?</h2><p class="micro">Demo form. Use example details — examples are saved only in this browser’s demo admin.</p><form id="contact-form" novalidate autocomplete="off"><label>Your name *<input name="name" required maxlength="80" aria-describedby="contact-name-error"><span id="contact-name-error" class="error"></span></label><label>Email address *<input name="email" type="email" required maxlength="120" aria-describedby="contact-email-error"><span id="contact-email-error" class="error"></span></label><label class="full">Phone number<input name="phone" type="tel" maxlength="30" aria-describedby="contact-phone-error"><span id="contact-phone-error" class="error"></span></label><label class="full">Your question *<textarea name="question" required rows="4" maxlength="2000" aria-describedby="contact-question-error"></textarea><span id="contact-question-error" class="error"></span></label><button class="btn full" type="submit">Send <span>→</span></button><p class="micro full">* Required fields. Send saves an example lead in this browser’s demo admin.</p></form><div id="contact-success" class="success hidden" role="status" tabindex="-1"><h3>Demo complete. Nothing was sent.</h3><p>Your example message passed validation. The fields have been cleared; no data was sent or saved.</p><button id="contact-again" class="btn">Try again ↺</button></div></div></section><section class="soft"><div class="wrap"><div class="sectionhead"><div><p class="eyebrow">Our offices</p><h2>Find your<br>local connection.</h2></div><p>UAE offices and regional contacts.<br>Contact the team before visiting.</p></div><div class="office-grid">${offices.map((o,i)=>`<article class="office-card"><div class="office-top"><span class="office-index">0${i+1}</span><span class="office-pin">${icon('pin')}</span></div><p class="eyebrow">${o.label}</p><h3>${o.city}</h3><p class="office-address">${o.address}</p><div class="office-links"><a href="tel:${o.phone.replace(/\s/g,'')}">${o.phone}</a>${o.email?`<a href="mailto:${o.email}">${o.email}</a>`:''}</div></article>`).join('')}</div></div></section>`;
let revealObserver;
function reveal(){revealObserver?.disconnect();if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;revealObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:550,easing:'cubic-bezier(.2,.7,.2,1)',fill:'none'});revealObserver.unobserve(e.target)}})},{threshold:.12});document.querySelectorAll('.sectionhead,.service,.fact,.steps>div,.wallet,.office-card,.contact-help,.formbox,.provider-cta').forEach(el=>revealObserver.observe(el))}
function setupForm(id,prefix,successId,againId){const form=document.getElementById(id);if(!form)return;const kind=id==='host-form'?'host':id==='provider-form'?'provider':'contact';form.addEventListener('input',()=>NTCRM.event('form_start',kind,kind),{once:true});form.addEventListener('submit',async e=>{e.preventDefault();if(form.dataset.sending)return;const fields=[...form.querySelectorAll('input,select,textarea')];let first;fields.forEach(input=>{const v=input.value.trim();let msg=input.required&&!v?'Please complete this field.':'';if(v&&(input.name==='email'||input.name==='contact'||input.name==='phone')){const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),phone=/^\+?[\d\s()-]+$/.test(v)&&v.replace(/\D/g,'').length>=7&&v.replace(/\D/g,'').length<=15;if(input.name==='email'&&!email)msg='Enter a valid email address.';if(input.name==='phone'&&!phone)msg='Enter a valid phone number.';if(input.name==='contact'&&!email&&!phone)msg='Enter a valid email or phone number.'}const error=document.getElementById(prefix+input.name+'-error');if(error)error.textContent=msg;input.setAttribute('aria-invalid',msg?'true':'false');if(msg&&!first)first=input});if(first){NTCRM.event('form_error',kind,kind);first.focus();return}const data=Object.fromEntries(fields.map(f=>[f.name,f.value.trim()]));let saved;const submit=form.querySelector('button[type=submit]');form.dataset.sending='true';if(submit)submit.disabled=true;let failure=form.querySelector('.submission-error');if(failure)failure.remove();try{saved=await NTForms.send(kind,data,form)}catch(error){failure=document.createElement('p');failure.className='submission-error full';failure.setAttribute('role','alert');failure.textContent=error.message;form.append(failure);return}finally{delete form.dataset.sending;if(submit)submit.disabled=false}NTCRM.lead(kind,data);NTCRM.event('form_submit',kind,kind);form.reset();form.classList.add('hidden');const success=document.getElementById(successId);success.querySelector('h3').textContent=saved.local?'Demo lead saved in this browser.':'Demo enquiry saved to Google Sheets.';success.querySelector('p').innerHTML='No enquiry was sent to NT.Payments. View this example in the <a class="text-link" href="#admin">demo admin →</a>. The form fields have been cleared.';success.classList.remove('hidden');success.focus()});document.getElementById(againId).onclick=()=>{form.classList.remove('hidden');document.getElementById(successId).classList.add('hidden');form.querySelector('input,select,textarea').focus()}}
const seoPaths={"home":"/","host":"/host-a-kiosk/","providers":"/providers/","wallet":"/wallet/","contacts":"/contact/","support":"/support/","find":"/find-a-kiosk/","services":"/payments/list-of-services/"};
function render(){let [route,anchor]=location.hash.slice(1).split('/');if(!route||(route!=='admin'&&!seoPaths[route]))route=Object.keys(seoPaths).find(key=>seoPaths[key]===location.pathname)||'home';if(route==='home'&&anchor==='find'){route='find';anchor=undefined}const page={host,providers,contacts,wallet,support:supportPage,find:finderPage,services:servicesPage,admin:NTCRM.page}[route]||home;document.getElementById('main').innerHTML=page();document.title=({"home":"Self-Service Payment Kiosks in UAE | NT.Payments Concept","host":"Host a Payment Kiosk | NT.Payments Website Concept","providers":"Payment Channels for Service Providers | NT.Payments Concept","wallet":"NT.Wallet Mobile Payments | Independent Design Concept","contacts":"Contact and Business Enquiries | NT.Payments Concept","supportPage":"Payment and Kiosk Support | NT.Payments Concept","finderPage":"Find a Payment Kiosk | NT.Payments Website Concept","services":"Payment Services Directory | NT.Payments Concept","admin":"Demo CRM | NT.Payments Concept"}[route]||"Self-Service Payment Kiosks in UAE | NT.Payments Concept");setMenu(false);document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.pathname===seoPaths[route||'home']&&!a.hash)a.setAttribute('aria-current','page')});if(anchor)requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView());else window.scrollTo(0,0);setupForm('host-form','','success','again');setupForm('contact-form','contact-','contact-success','contact-again');setupForm('provider-form','provider-','provider-success','provider-again');setupCountry();setupFinder();NTForms.label();NTCRM.setup();document.body.classList.remove('lead-open');if(route!=='admin')NTCRM.event('page_view',route||'home');document.querySelectorAll('a[href^="#"]').forEach(link=>{const [key,sub]=link.getAttribute('href').slice(1).split('/');if(key==='admin')link.setAttribute('href','/#admin');else if(seoPaths[key])link.setAttribute('href',seoPaths[key]+(sub?'#'+key+'/'+sub:''))});reveal()}

function setupCountry(){const form=document.getElementById('host-form');if(!form)return;const country=form.elements.country;const sync=()=>{document.getElementById('region-field').innerHTML=country.value==='UAE'?`Emirate<select name="emirate" required aria-describedby="emirate-error"><option value="">Select emirate</option>${['Abu Dhabi','Dubai','Sharjah','Ajman','Umm Al Quwain','Ras Al Khaimah','Fujairah'].map(x=>`<option>${x}</option>`).join('')}</select><span class="error" id="emirate-error"></span>`:`City / region<input name="emirate" required maxlength="100" placeholder="${country.value==='KSA'?'e.g. Riyadh':'e.g. Doha'}" aria-describedby="emirate-error"><span class="error" id="emirate-error"></span>`};country.addEventListener('change',sync);form.addEventListener('reset',()=>queueMicrotask(sync))}
const stores=()=>`<div class="store-buttons"><a class="store-button" href="https://apps.apple.com/ae/app/nt-wallet/id1436941584" target="_blank" rel="noopener" aria-label="Download NT.Wallet on the App Store"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M16.7 12.7c0-2 1.6-3 1.7-3.1-1-1.5-2.6-1.7-3.2-1.7-1.3-.1-2.5.8-3.2.8s-1.7-.8-2.8-.7c-1.5 0-2.9.9-3.6 2.2-1.5 2.6-.4 6.5 1 8.6.7 1 1.5 2.1 2.6 2.1s1.5-.7 2.9-.7 1.8.7 3 .7 1.9-1 2.6-2c.8-1.2 1.2-2.4 1.2-2.5-.1 0-2.2-.8-2.2-3.7ZM14.7 6.6c.6-.8 1.1-1.9 1-3-.9 0-2.1.6-2.8 1.4-.6.7-1.2 1.8-1 2.9 1 .1 2.1-.5 2.8-1.3Z"/></svg><span><small>Download on the</small><strong>App Store</strong></span></a><a class="store-button" href="https://play.google.com/store/apps/details?id=com.ntpayments.ntwallet" target="_blank" rel="noopener" aria-label="Get NT.Wallet on Google Play"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#42d2a5" d="M3 2 14 12 3 22Z"/><path fill="#62bcff" d="m3 2 13 7-2 3Z"/><path fill="#ffd452" d="m14 12 2-3 5 3-5 3Z"/><path fill="#ff697e" d="m3 22 11-10 2 3Z"/></svg><span><small>Get it on</small><strong>Google Play</strong></span></a></div>`;
const wallet=()=>`<div class="wallet-page"><section class="wrap wallet-hero"><div><div class="breadcrumb"><a href="#home">Home</a> / NT.Wallet</div><p class="eyebrow">Your everyday payment companion</p><h1>A little less admin.<br><em>A lot more living.</em></h1><p class="intro">Mobile recharges, bills and digital essentials. Bring your everyday payments together with NT.Wallet.</p>${stores()}<p class="micro">Available for iPhone and Android. Check the store listing for device compatibility.</p><div class="wallet-points"><span>${icon('mobile')} Local & international recharge</span><span>${icon('pay')} Wallet & card payments</span></div></div><div class="wallet-hero-art"><div class="glass-orb orb-one"></div><div class="glass-orb orb-two"></div>${walletPhone()}<span class="glass-tag">Your day. In better balance.</span></div></section><div class="wallet-value-strip"><span>Recharge a mobile</span><i>●</i><span>Pay everyday bills</span><i>●</i><span>Stay in control</span></div></div><section class="wrap"><div class="sectionhead"><div><p class="eyebrow">Small tasks. More possibilities.</p><h2>One app for<br>your everyday essentials.</h2></div><p>Choose your service, review the details and pay. Explore current availability and fees in the app.</p></div><div class="grid">${[['mobile','Keep the conversation going','Recharge local mobile services, including du and Etisalat, or send a mobile top-up abroad.'],['utility','Take care of your bills','Explore utility and transport payments alongside everyday digital services.'],['shopping','Make room for downtime','Discover gaming, entertainment and digital purchases through the available service catalogue.']].map(([i,t,d])=>`<article class="service"><span class="icon">${icon(i)}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="soft"><div class="wrap wallet-bridge"><div class="bridge-art"><span class="bridge-kiosk">${icon('pay')}<strong>NT.Payments</strong><small>Cash at the kiosk</small></span><span class="bridge-connect">⇄</span><span class="bridge-app">${icon('mobile')}<strong>NT.Wallet</strong><small>Payments on your phone</small></span></div><div><p class="eyebrow">Connected to your neighbourhood</p><h2>Start at a kiosk.<br>Continue on your phone.</h2><p class="intro">Recharge your wallet with cash through NT.Payments kiosks. Then use your wallet balance for available services in the app.</p><a class="btn" href="#find">Find a kiosk <span>→</span></a><p class="micro" style="margin-top:16px">Follow the app and kiosk instructions. Check recharge details and any fees before confirming.</p></div></div></section><section class="wrap"><p class="eyebrow">Your payments, together</p><h2>More clarity.<br>Less going back and forth.</h2><div class="facts"><div class="fact"><strong>Choose how to pay</strong><p>Use available bank card, wallet balance or bonus payment options. Check eligibility within the app.</p></div><div class="fact"><strong>Keep track</strong><p>View transaction history and manage your balance from your phone.</p></div><div class="fact"><strong>Help within reach</strong><p>Get assistance through the app’s online customer support when you need it.</p></div></div></section><section class="wrap" style="padding-top:0"><div class="wallet-download" id="download"><p class="eyebrow">Meet your next everyday essential</p><h2>Life keeps moving.<br>Take your payments with you.</h2><p>Download NT.Wallet and explore the services available to you.</p>${stores()}<p class="micro">The interface shown on this site is an independent redesign concept. The downloaded app has its own current interface.</p></div></section><section class="wrap faq-form" style="padding-top:0"><div><p class="eyebrow">A few things to know</p><h2>Before your<br>first payment.</h2><a class="text-link" href="#contacts">Need help? Contact us →</a></div><div class="faq"><details><summary>Can I top up using cash?</summary><p>NT.Wallet supports recharging via NT.Payments kiosks. Follow the current app and kiosk instructions for your account.</p></details><details><summary>Which services are available?</summary><p>Explore mobile recharges, utilities, transport, gaming and entertainment in the app. Availability, fees and payment options depend on the service.</p></details><details><summary>Is this the app’s current design?</summary><p>The smartphone on this website shows an independent interface concept with sample data. Use the store listing to see the actual app.</p></details></div></section>`;

const supportPage=()=>`<div class="host-hero"><section class="wrap hero support-hero"><div><div class="breadcrumb"><a href="#home">Home</a> / Support</div><p class="eyebrow">Customer care</p><h1>A real person.<br><em>A clearer next step.</em></h1><p class="intro">A payment question, a kiosk issue or help getting started? Our support team is here to help you find the next step.</p><div class="actions"><a class="btn" href="tel:600542521">Call 600 542 521 <span>→</span></a><a class="text-link" href="https://wa.me/971501956593" target="_blank" rel="noopener">Chat on WhatsApp ↗</a></div><p class="micro">UAE customer support · 7 days · 08:00–23:00<br>Arabic · English · Urdu · Hindi</p></div><div class="support-photo"><img src="/assets/support-team.png" alt="Customer support specialist wearing a headset at her desk"><div class="support-photo-label">People helping people.</div></div></section></div><section class="wrap"><div class="sectionhead"><div><p class="eyebrow">Choose how to reach us</p><h2>Let’s get<br>your question moving.</h2></div><p>Keep your transaction reference nearby so the team can understand your payment.</p></div><div class="grid"><article class="service"><span class="icon">${icon('mobile')}</span><h3>Give us a call</h3><p>Speak to UAE customer care about your payment or kiosk experience.</p><div class="actions"><a class="text-link" href="tel:600542521">600 542 521 →</a></div></article><article class="service"><span class="icon">${icon('connect')}</span><h3>Message on WhatsApp</h3><p>Start a conversation with customer support using WhatsApp.</p><div class="actions"><a class="text-link" href="https://wa.me/971501956593" target="_blank" rel="noopener">+971 50 195 65 93 ↗</a></div></article><article class="service"><span class="icon">${icon('mail')}</span><h3>Send an email</h3><p>Describe your question and include the relevant transaction details.</p><div class="actions"><a class="text-link" href="mailto:support@ntpayments.com">support@ntpayments.com ↗</a></div></article></div></section><section class="soft"><div class="wrap"><p class="eyebrow">Before you contact us</p><h2>A few details.<br>A more useful conversation.</h2><div class="steps"><div><div class="step-num">01 / TRANSACTION</div><h3>Your payment reference</h3><p>Have your receipt or transaction reference, payment amount and date ready.</p></div><div><div class="step-num">02 / LOCATION</div><h3>Where you paid</h3><p>Note the kiosk location or kiosk number, if available, and which service you selected.</p></div><div><div class="step-num">03 / QUESTION</div><h3>What happened</h3><p>Explain what you expected and what you saw. Never share your PIN, password or one-time code.</p></div></div></div></section><section class="wrap faq-form"><div><p class="eyebrow">Payment status</p><h2>A quick way<br>to check in.</h2><p class="intro">You can also check a transaction through the NT.Payments UAE Telegram bot.</p><div class="actions"><a class="btn" href="https://t.me/kioskuae_bot" target="_blank" rel="noopener">Open payment status bot <span>↗</span></a></div><p class="micro">Opens Telegram. Follow the bot instructions; this website does not access your transactions.</p></div><div class="faq"><details><summary>My payment hasn’t appeared. What should I do?</summary><p>Keep your receipt and transaction reference. Contact support with the amount, date, selected service and kiosk details so the team can look into it.</p></details><details><summary>Can I ask which services are available?</summary><p>Yes. Explore the service directory or ask customer care about the service you need.</p><a class="text-link" href="/payments/list-of-services/">Explore the service directory →</a></details><details><summary>I need help with NT.Wallet.</summary><p>Use the in-app support options or contact customer care. Have the relevant transaction details ready.</p><a class="text-link" href="#wallet">Explore NT.Wallet →</a></details><details><summary>I’m contacting you about a partnership.</summary><p>For hosting, provider integration or advertising enquiries, use the relevant business page or contact our team.</p><a class="text-link" href="#contacts">Business contacts →</a></details></div></section><section class="wrap" style="padding-top:0"><div class="regional-support"><div><p class="eyebrow">Outside the UAE?</p><h3>Saudi Arabia customer support</h3><p>Call or message the KSA support team.</p></div><div class="regional-links"><a class="text-link" href="tel:+966555899467">+966 555 899 467</a><a class="text-link" href="https://wa.me/966555899467" target="_blank" rel="noopener">WhatsApp ↗</a><a class="text-link" href="#contacts">Other regional contacts →</a></div></div></section>`;

