const finderPage=()=>`<section class="wrap country-finder"><div class="breadcrumb"><a href="#home">Home</a> / Find a kiosk</div><p class="eyebrow">Your next payment stop</p><h1>Everyday payments.<br><em>Find your place to start.</em></h1><p class="intro">Choose a city to explore its map.</p><div id="country-selection"><button class="city-summary" id="city-summary" type="button" aria-expanded="false" aria-controls="city-options"><span id="city-summary-name">🇦🇪 Dubai <small>UAE</small></span><span class="city-summary-change">Change <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></span></button><div id="city-options"><div class="country-step"><span>01</span><h2>Where are you looking?</h2></div><div class="country-grid">${locatorCountries.map(c=>`<button type="button" class="country-card" data-country="${c.id}" aria-label="Show map of ${c.city}, ${c.name}"><span class="country-card-top"><span class="country-flag" aria-hidden="true">${c.flag}</span><span class="country-code">${c.short}</span></span><span class="country-card-copy"><strong>${c.city}</strong><small>${c.name}</small></span><span class="country-card-bottom">Explore map <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></span></button>`).join('')}</div><p class="country-data-note">Maps are available to explore. Verified kiosk locations will be added once the location directory is connected.</p></div></div><div id="country-map-view"><div class="country-map-toolbar"><button class="country-back" type="button" id="country-back">↑ Choose another city</button><span class="country-map-step">02 / EXPLORE</span></div><div class="country-map-heading"><div><p class="eyebrow">Find a kiosk</p><h2 id="country-map-title" tabindex="-1"></h2></div><span class="map-availability">Kiosk locations coming next</span></div><div class="country-map-frame" id="country-map-frame"></div><p class="country-map-note" role="status">No kiosk markers are shown yet. This Google map shows the selected city area; it does not identify available kiosks.</p><div class="country-map-assist"><div><h3>Need a kiosk location now?</h3><p>Contact our team to confirm a location before you travel.</p></div><a class="btn" href="#support">Get help finding a kiosk <span>→</span></a></div></div></section>`;
function setupFinder(){const selection=document.getElementById('country-selection');if(!selection)return;const view=document.getElementById('country-map-view'),frame=document.getElementById('country-map-frame'),title=document.getElementById('country-map-title');const buttons=[...selection.querySelectorAll('[data-country]')];function choose(id,scroll){const country=locatorCountries.find(c=>c.id===id);title.textContent=country.city+' · '+country.name;document.getElementById('city-summary-name').innerHTML=country.flag+' '+country.city+' <small>'+country.short+'</small>';selection.classList.add('city-collapsed');document.getElementById('city-summary').setAttribute('aria-expanded','false');buttons.forEach(button=>{const active=button.dataset.country===id;button.setAttribute('aria-pressed',String(active));button.classList.toggle('selected',active)});frame.innerHTML=`<iframe title="Google Maps — ${country.city}, ${country.name}" src="${country.embed}" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe>`;if(scroll&&!matchMedia('(max-width: 680px)').matches){title.focus();view.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}if(scroll&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.getElementById('city-summary').animate([{transform:'scale(.97)'},{transform:'scale(1.012)',offset:.65},{transform:'scale(1)'}],{duration:340,easing:'cubic-bezier(.2,.7,.2,1)'});frame.animate([{opacity:.6},{opacity:1}],{duration:240})}}buttons.forEach(button=>button.onclick=()=>choose(button.dataset.country,true));document.getElementById('city-summary').onclick=()=>{const expanded=document.getElementById('city-summary').getAttribute('aria-expanded')!=='true';selection.classList.toggle('city-collapsed',!expanded);document.getElementById('city-summary').setAttribute('aria-expanded',String(expanded))};document.getElementById('country-back').onclick=()=>{selection.classList.remove('city-collapsed');document.getElementById('city-summary').setAttribute('aria-expanded','true');selection.scrollIntoView({block:'start',behavior:'auto'});buttons.find(button=>button.getAttribute('aria-pressed')==='true')?.focus()};choose('UAE',false)}

function setMenu(open,restoreFocus=false){const toggle=document.querySelector('.menu'),nav=document.querySelector('nav');nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu');document.body.classList.toggle('menu-open',open);const scrim=document.querySelector('.menu-scrim');if(scrim){scrim.hidden=!open;scrim.setAttribute('aria-hidden',String(!open))}if(restoreFocus)toggle.focus()}
document.querySelector('.menu').onclick=()=>setMenu(document.querySelector('.menu').getAttribute('aria-expanded')!=='true');
document.querySelector('.menu-scrim').onclick=()=>setMenu(false,true);
document.querySelector('nav').addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});
document.addEventListener('keydown',e=>{if(document.querySelector('.menu').getAttribute('aria-expanded')!=='true')return;if(e.key==='Escape'){setMenu(false,true);return}if(e.key==='Tab'){const links=[document.querySelector('.menu'),...document.querySelectorAll('nav a')];const first=links[0],last=links[links.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
matchMedia('(min-width: 681px)').addEventListener('change',e=>{if(e.matches)setMenu(false)});
window.addEventListener('hashchange',render);render();
